(function(root){
 'use strict';
 const layouts={
  tall:{width:910,height:1729,doors:{luch:[39,6,22,7],lab:[12,19,28,7],technical:[70,19,26,7],kitchen:[12,48,27,7],captain:[70,48,27,7],crate:[52,77,12,7],send:[37,88,25,11]}},
  wide:{width:1672,height:941,doors:{luch:[44,7,12,12],lab:[9,13,12,13],technical:[79,13,12,13],kitchen:[9,50,12,13],captain:[79,50,12,13],crate:[55,80,7,9],send:[44,94,12,6]}}
 };
 function fit(w,h,iw,ih){const scale=Math.min(w/iw,h/ih);return {width:iw*scale,height:ih*scale,x:(w-iw*scale)/2,y:(h-ih*scale)/2};}
 function markup(rooms,t,finished,cloth){return `<div class="hub-map-plane" id="hub-map-plane">${Object.entries(rooms).map(([id,r])=>`<button class="map-door" data-map="${id}" data-room="${id}" aria-label="${r.name}" title="${r.name}"><span>${r.name}</span></button>`).join('')}<button class="map-door" data-map="luch" id="hub-luch" aria-label="${t('Кабинет ЛУЧа','LUCH office')}" title="${t('Кабинет ЛУЧа','LUCH office')}"><span>${t('ЛУЧ','LUCH')}</span></button>${cloth}<button class="map-target" data-map="crate" id="crate" aria-label="${t('Ящик с грузом','Cargo crate')}" title="${t('Ящик с грузом','Cargo crate')}"></button>${finished?`<button class="map-target map-depart" data-map="send" id="send" aria-label="${t('В капсулу','To the capsule')}">${t('В капсулу','To the capsule')} ↧</button>`:''}</div>`;}
 function attach(view,bg,screen,data){const plane=screen.querySelector('.hub-map-plane');function update(){const wide=view.clientWidth>=view.clientHeight,l=layouts[wide?'wide':'tall'],top=document.querySelector('.hud').getBoundingClientRect().bottom-view.getBoundingClientRect().top+8,bottom=view.getBoundingClientRect().bottom-document.querySelector('.bottom-hud').getBoundingClientRect().top+8,g=fit(view.clientWidth,Math.max(1,view.clientHeight-top-bottom),l.width,l.height);screen.classList.toggle('wide-map',wide);screen.classList.toggle('english-map',root.GameLocale?.lang==='en');bg.src=wide?data.hubWide:data.hub;for(const el of [bg,plane]){el.style.width=g.width+'px';el.style.height=g.height+'px';el.style.transform=`translate(${g.x}px,${g.y+top}px)`;}plane.querySelectorAll('[data-map]').forEach(el=>{const [x,y,w,h]=l.doors[el.dataset.map];Object.assign(el.style,{left:x+'%',top:y+'%',width:w+'%',height:h+'%'});});}
 const ro=new ResizeObserver(update);ro.observe(view);window.addEventListener('resize',update);window.visualViewport?.addEventListener('resize',update);update();return {destroy(){ro.disconnect();window.removeEventListener('resize',update);window.visualViewport?.removeEventListener('resize',update);bg.removeAttribute('style');}};}
 root.HubMap={layouts,fit,markup,attach};if(typeof module!=='undefined'&&module.exports)module.exports={layouts,fit};
})(typeof window!=='undefined'?window:globalThis);
